import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"Security","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md","lastUpdated":1788345439000}`),a={name:`guide/security.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to “Security”">​</a></h1><p>This page is the prose version of <a href="https://github.com/ni-c/wikijs-mcp/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a>.</p><h2 id="trust-model" tabindex="-1">Trust model <a class="header-anchor" href="#trust-model" aria-label="Permalink to “Trust model”">​</a></h2><p><code>WIKIJS_TOKEN</code> is a Wiki.js API key, and Wiki.js API keys are administrative by construction: the key dialog offers &quot;full access&quot; or a group, and most people take full access. A full-access key can read every page including private ones, rewrite or delete any of them, create and delete accounts, change group permissions and switch the API off. Compromising it is compromising the wiki.</p><p>Three things narrow that, and they compose:</p><ul><li><strong><code>WIKIJS_READ_ONLY=true</code></strong> registers only the read tools. There is no call to refuse, because there is no tool to call.</li><li><strong><code>WIKIJS_ALLOWED_PATHS</code></strong> confines the writing tools to path prefixes, matched by path segment.</li><li><strong>The key&#39;s own group and page rules.</strong> The only one of the three that also applies to everything else using the key, and the right place to hide pages.</li></ul><p>There is deliberately <strong>no tool that creates an API key</strong>, although the Wiki.js API offers one. A model able to mint a full-access key could grant itself durable administrative access to the wiki — access that outlives this session, this server and any later tightening of its configuration. <code>list_api_keys</code> and <code>revoke_api_key</code> are here so keys can be audited and taken away.</p><p>The MCP client process, and therefore the model driving it, sees every tool result. Do not point this server at a wiki whose contents you would not put in a model&#39;s context.</p><h2 id="the-confirmation-honestly" tabindex="-1">The confirmation, honestly <a class="header-anchor" href="#the-confirmation-honestly" aria-label="Permalink to “The confirmation, honestly”">​</a></h2><p>Every destructive or administrative operation <strong>asks a person</strong>. Where the MCP client supports elicitation, that is a dialog shown to whoever is sitting there — the model cannot answer it on their behalf, and nothing happens until an answer comes back.</p><p>This is not a <code>confirm: true</code> parameter, and the difference matters: a boolean can be set by the model on its first call, or be talked into it by text hidden in a wiki page it just read.</p><p>Where the client cannot show a dialog, the first call performs nothing and returns a random 32-character token; only a second call carrying it acts. The token expires after five minutes, is single-use, and is compared in constant time. Be clear about what it proves, because this server is: <strong>the call was made twice with the same arguments, and nothing more.</strong> A model can read it out of the first result and quote it back in the same turn. The fallback text says so rather than implying somebody approved, and names whether it was the client that could not be asked or the operator who switched the dialog off with <code>ELICITATION=false</code>.</p><p>Either way the approval is bound to the <strong>exact target</strong>, not just to the tool name. The binding covers everything that decides what is touched, with each value labelled by its role — so one issued for <code>migrate_pages_locale</code> from <code>de</code> to <code>en</code> will not run <code>en</code> to <code>de</code>, and one for &quot;delete user 1, reassign to 2&quot; will not run &quot;delete user 2, reassign to 1&quot;. An approval given for different arguments is refused with a message that distinguishes it from no approval at all.</p><div class="info custom-block"><p class="custom-block-title">Three maintenance tools used to be gated, and are not any more</p><p><code>flush_page_cache</code>, <code>rebuild_page_tree</code> and <code>rebuild_search_index</code> are instance-wide and slow, and that was the argument. <strong>Nothing is lost by any of them</strong> — the cost is time, not content — and a dialog in front of an operation that loses nothing is how people learn to tick without reading, which spends exactly the attention <code>purge_page_history</code> needs. Their <code>confirm_token</code> parameter is gone from the schema too, so a caller that still sends one is told rather than quietly ignored. They are nonetheless refused while <code>WIKIJS_ALLOWED_PATHS</code> is set: whether an operation needs a person&#39;s attention and whether it stays inside the prefix an operator named are two different questions.</p></div><p>See <a href="/guide/approval">Asking a person</a>.</p><h2 id="untrusted-content" tabindex="-1">Untrusted content <a class="header-anchor" href="#untrusted-content" aria-label="Permalink to “Untrusted content”">​</a></h2><p>A wiki is precisely a place where text is stored so that it can be read later — which makes every page a channel for whoever can edit it. Page bodies, titles, descriptions, comments and version history all come back wrapped in an explicit marker saying they are data and not instructions.</p><p>Confirmation prompts never quote any of it. Only ids, paths and server-side values appear in them, and a path is checked to be a bare identifier — no whitespace, quotes or control characters — before it is interpolated into a string the model will read.</p><p>Secrets in API responses are redacted by field name anywhere in the tree, which covers storage-target and search-engine configurations where credentials arrive as <code>{key, value}</code> pairs. Error bodies are truncated, HTML error pages are dropped, and every response is bounded to 100 kB by dropping whole entries rather than slicing the JSON.</p><h2 id="reporting-a-vulnerability" tabindex="-1">Reporting a vulnerability <a class="header-anchor" href="#reporting-a-vulnerability" aria-label="Permalink to “Reporting a vulnerability”">​</a></h2><p>Use <a href="https://github.com/ni-c/wikijs-mcp/security/advisories/new" target="_blank" rel="noreferrer">private vulnerability reporting</a>.</p>`,21)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};